//! Differential replay for `src/engine/battleScriptOrwordOpcode.ts`.
//! Expected state, controls, direct-handler errors, and registration results
//! are generated by running the canonical TypeScript leaf.

use std::collections::BTreeSet;

use factory_core::battle_script_orword::*;
use factory_core::battle_script_orword_vectors_gen::*;

fn instruction(
    value: BattleScriptOrwordVectorInstruction,
) -> BattleScriptOrwordInstruction<'static> {
    BattleScriptOrwordInstruction {
        opcode_name: value.opcode_name,
        program_counter: value.program_counter,
        opcode_id: value.opcode_id,
        dispatcher: value.dispatcher,
        operands: value.operands,
    }
}

#[test]
fn complete_projected_outputs_controls_errors_repetitions_and_immutable_inputs_match_typescript() {
    assert_eq!(BATTLE_SCRIPT_ORWORD_CASES.len(), 66);
    for (case_index, case) in BATTLE_SCRIPT_ORWORD_CASES.iter().enumerate() {
        execute_case(case_index, case);
    }
}

fn execute_case(case_index: usize, case: &BattleScriptOrwordVectorCase) {
    let input = case.initial_rules;
    let before = input;
    let mut current = input;
    let mut controls = [None; 3];
    let mut actual_error = None;

    for (application, control_slot) in controls
        .iter_mut()
        .enumerate()
        .take(usize::from(case.applications))
    {
        let prior = current;
        match apply_battle_script_orword(instruction(case.instruction), &current) {
            Ok(outcome) => {
                assert_transition_shape(case_index, case, application, prior, outcome);
                *control_slot = Some(outcome.control);
                current = outcome.rules;
            }
            Err(error) => {
                actual_error = Some(error.to_string());
                break;
            }
        }
    }

    assert_eq!(
        input, before,
        "case {case_index} {}: native transformation mutated input",
        case.label,
    );
    match (actual_error, case.expected_rules, case.expected_error) {
        (None, Some(expected), None) => {
            assert_eq!(
                controls, case.controls,
                "case {case_index} {}: canonical control sequence",
                case.label,
            );
            assert_eq!(
                current, expected,
                "case {case_index} {}: complete projected output",
                case.label,
            );
        }
        (Some(actual), None, Some(expected)) => {
            assert_eq!(
                controls, case.controls,
                "case {case_index} {}: errors must not produce controls",
                case.label,
            );
            assert_eq!(
                actual, expected,
                "case {case_index} {}: exact canonical direct-handler error",
                case.label,
            );
        }
        (actual, expected, expected_error) => panic!(
            "case {case_index} {}: generated result shape disagrees with native result: error={actual:?}, expected={expected:?}, expected_error={expected_error:?}",
            case.label,
        ),
    }
}

fn assert_transition_shape(
    case_index: usize,
    case: &BattleScriptOrwordVectorCase,
    application: usize,
    prior: BattleScriptOrwordRules,
    outcome: BattleScriptOrwordOutcome,
) {
    assert_eq!(
        outcome.control,
        BattleScriptOrwordControl::Advance,
        "case {case_index} {} application {application}: Cmd_orword must advance",
        case.label,
    );
    let expected_value =
        resolve_battle_script_orword_value(instruction(case.instruction).operands[1].expression)
            .unwrap_or_else(|| {
                panic!(
            "case {case_index} {} application {application}: successful input was not decodable",
            case.label,
        )
            });
    assert_eq!(
        outcome.rules.hit_marker,
        prior.hit_marker | expected_value,
        "case {case_index} {} application {application}: u32 OR result",
        case.label,
    );
    assert_eq!(
        outcome.rules.battlers, prior.battlers,
        "case {case_index} {} application {application}: changed battlers",
        case.label,
    );
    assert_eq!(
        outcome.rules.selector_roles, prior.selector_roles,
        "case {case_index} {} application {application}: changed selector roles",
        case.label,
    );
    assert_eq!(
        outcome.rules.siblings, prior.siblings,
        "case {case_index} {} application {application}: changed sibling state",
        case.label,
    );
}

#[test]
fn all_43_canonical_sites_all_11_named_terms_compounds_and_u32_edges_are_present() {
    assert_eq!(BATTLE_SCRIPT_ORWORD_CALL_SITE_EVIDENCE.len(), 43);
    assert_eq!(
        BATTLE_SCRIPT_ORWORD_U32_EDGE_DOMAIN,
        [0, 1, 0x8000_0000, u32::MAX],
    );
    assert_eq!(
        BATTLE_SCRIPT_ORWORD_VALUE_CATEGORY_CENSUS,
        [
            ("single-term", 29),
            ("compound-four-term", 1),
            ("compound-two-term", 11),
            ("compound-three-term", 2),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_ORWORD_TERM_USE_CENSUS,
        [
            ("HITMARKER_IGNORE_BIDE", 1),
            ("HITMARKER_IGNORE_SUBSTITUTE", 27),
            ("HITMARKER_ATTACKSTRING_PRINTED", 3),
            ("HITMARKER_NO_PPDEDUCT", 5),
            ("HITMARKER_IGNORE_ON_AIR", 4),
            ("HITMARKER_IGNORE_UNDERGROUND", 1),
            ("HITMARKER_IGNORE_UNDERWATER", 2),
            ("HITMARKER_PASSIVE_HP_UPDATE", 12),
            ("HITMARKER_GRUDGE", 1),
            ("HITMARKER_ALLOW_NO_PP", 2),
            ("HITMARKER_CHARGING", 3),
        ],
    );

    let expected_terms = BATTLE_SCRIPT_ORWORD_HITMARKER_TERMS
        .into_iter()
        .collect::<BTreeSet<_>>();
    let observed_terms = BATTLE_SCRIPT_ORWORD_TERM_EVIDENCE
        .iter()
        .map(|term| (term.expression, term.value))
        .collect::<BTreeSet<_>>();
    assert_eq!(observed_terms, expected_terms);

    let all_site_values = BATTLE_SCRIPT_ORWORD_CALL_SITE_EVIDENCE
        .iter()
        .map(|site| site.resolved_value)
        .collect::<BTreeSet<_>>();
    assert!(all_site_values.contains(&0x0110_0120));
    assert!(all_site_values.contains(&0x0010_0100));
    assert!(all_site_values.contains(&0x0080_0c00));
    assert!(all_site_values.contains(&BATTLE_SCRIPT_HITMARKER_CHARGING));
}

#[test]
fn registration_replays_exact_first_binding_and_ordered_validation_failures() {
    assert_eq!(BATTLE_SCRIPT_ORWORD_REGISTRATION_CASES.len(), 18);
    for case in BATTLE_SCRIPT_ORWORD_REGISTRATION_CASES {
        let inputs = case
            .instructions
            .iter()
            .copied()
            .map(instruction)
            .collect::<Vec<_>>();
        let before = inputs.clone();
        let actual = register_battle_script_orword_handler(&inputs);
        assert_eq!(inputs, before, "{}: registration mutated input", case.label);
        match (actual, case.expected_bindings, case.expected_error) {
            (Ok(registration), [expected], None) => assert_eq!(
                registration.opcode_id, *expected,
                "{}: registration binding",
                case.label,
            ),
            (Err(error), [], Some(expected)) => assert_eq!(
                error.to_string(),
                expected,
                "{}: registration error",
                case.label,
            ),
            (actual, bindings, expected_error) => panic!(
                "{}: registration shape mismatch {actual:?} {bindings:?} {expected_error:?}",
                case.label,
            ),
        }
    }

    let first_binding = BATTLE_SCRIPT_ORWORD_REGISTRATION_CASES
        .iter()
        .find(|case| case.label == "first_opcode_id_becomes_binding")
        .expect("first binding vector");
    assert_eq!(first_binding.expected_bindings, [0xaa]);
    let later_opcode = BATTLE_SCRIPT_ORWORD_REGISTRATION_CASES
        .iter()
        .find(|case| case.label == "later_opcode_id_is_ignored")
        .expect("later opcode vector");
    assert_eq!(
        later_opcode.expected_bindings,
        [BATTLE_SCRIPT_ORWORD_OPCODE]
    );
}
